// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.9;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/MarvinInu.sol";

contract MockWETH {
    function deposit() public payable {}
    function withdraw(uint) public {}
}

contract MockPair {
    function sync() external {
        // Do nothing - just satisfy interface
    }
}

contract MockFactory {
    address public pair;

    constructor(address _pair) {
        pair = _pair;
    }

    function createPair(address, address) external view returns (address) {
        return pair;
    }
}

contract MockRouter {
    address public factory;
    address public WETH;

    function initialize(address _factory, address _weth) external {
        factory = _factory;
        WETH = _weth;
    }
}

contract MarvinInuBurnTest is Test {
    MarvinInu token;
    MockWETH mockWETH;
    MockPair mockPair;
    MockFactory mockFactory;

    address constant REAL_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address owner = makeAddr("owner");
    address pairAddress;

    function setUp() public {
        // Deploy mock chain components
        mockWETH = new MockWETH();
        mockPair = new MockPair();
        mockFactory = new MockFactory(address(mockPair));

        // Deploy router template
        MockRouter mockRouterTemplate = new MockRouter();
        bytes memory mockRouterCode = address(mockRouterTemplate).code;
        vm.etch(REAL_ROUTER, mockRouterCode);

        // Initialize the mock router at the real address
        (bool success, ) = REAL_ROUTER.call(
            abi.encodeWithSignature(
                "initialize(address,address)",
                address(mockFactory),
                address(mockWETH)
            )
        );
        require(success, "Router initialization failed");

        // Deploy & configure MarvinInu token
        vm.startPrank(owner);
        token = new MarvinInu();
        token.disableTransferDelay();
        token.removeLimits();
        token.enableTrading();
        vm.stopPrank();

        pairAddress = token.uniswapV2Pair();
    }

    function testLpBurnManipulation() public {
        // Prepare for manipulation
        uint256 initialPairBalance = token.balanceOf(pairAddress);
        vm.prank(owner);
        token.transfer(pairAddress, initialPairBalance / 100); // Transfer 1% to inflate LP

        uint256 manipulatedBalance = token.balanceOf(pairAddress);
        uint256 expectedBurnAmount = manipulatedBalance * 1000 / 10000; // 10% of inflated balance

        // Fast-forward past burn cooldown
        vm.warp(block.timestamp + 30 minutes + 1);

        // Execute burn
        vm.prank(owner);
        token.manualBurnLiquidityPairTokens(1000); // Burn 10%

        // Verify burned amount based on manipulated balance
        uint256 actualBurnAmount = manipulatedBalance - token.balanceOf(pairAddress);
        assertApproxEqAbs(
            actualBurnAmount, 
            expectedBurnAmount, 
            1e16,  // Account for minor rounding
            "Burn used manipulated balance"
        );
    }
}
